use rand::distr::Alphanumeric; use rand::{rng, Rng}; use serde::Deserialize; use std::io::{BufRead, BufReader}; use std::process::{Child, Command, Stdio}; use std::sync::Mutex; use tauri::Manager;
struct Core(Mutex<Child>, u16, String);
#[derive(Deserialize)] struct Ready { port: u16 }
fn launch() -> Result<Core, String> { let token: String = rng().sample_iter(&Alphanumeric).take(48).map(char::from).collect(); let python = std::env::var("BOOK_OS_PYTHON").unwrap_or_else(|_| "python3".into()); let source_path = std::env::var("BOOK_OS_CORE_PYTHONPATH").unwrap_or_else(|_| format!("{}/../../../services/local-core/src", env!("CARGO_MANIFEST_DIR"))); let mut child = Command::new(python).args(["-m", "book_os_core"]).env("BOOK_OS_SESSION_TOKEN", &token).env("PYTHONPATH", source_path).stdout(Stdio::piped()).spawn().map_err(|e| e.to_string())?; let stdout = child.stdout.take().ok_or("sidecar stdout unavailable")?; let mut reader = BufReader::new(stdout); let mut ready_line = String::new(); reader.read_line(&mut ready_line).map_err(|e| e.to_string())?; let ready: Ready = serde_json::from_str(&ready_line).map_err(|e| e.to_string())?; Ok(Core(Mutex::new(child), ready.port, token)) }
#[tauri::command] fn core_health(core: tauri::State<'_, Core>) -> Result<serde_json::Value, String> { let url = format!("http://127.0.0.1:{}/health", core.1); let text = ureq::get(&url).header("Authorization", &format!("Bearer {}", core.2)).call().map_err(|e| e.to_string())?.body_mut().read_to_string().map_err(|e| e.to_string())?; serde_json::from_str(&text).map_err(|e| e.to_string()) }
fn main() { tauri::Builder::default().setup(|app| { app.manage(launch().map_err(|e| std::io::Error::other(e))?); Ok(()) }).invoke_handler(tauri::generate_handler![core_health]).on_window_event(|window, event| if matches!(event, tauri::WindowEvent::Destroyed) { if let Some(core) = window.app_handle().try_state::<Core>() { let _ = core.0.lock().map(|mut child| child.kill()); }}).run(tauri::generate_context!()).expect("BOOK OS desktop error"); }
